t.script:
document.addEventListener('DOMContentLoaded', function() {
    let container = document.getElementById('guardians_container');
    let btnAdd = document.getElementById('btnAddGuardian');
    let nextIdx = document.querySelectorAll('.guardian-row').length;

    btnAdd.addEventListener('click', function() {
        let firstRow = document.querySelector('.guardian-row');
        let newRow = firstRow.cloneNode(true);

        newRow.id = 'guardian_row_' + nextIdx;
        newRow.querySelector('.g-index-label').innerText = nextIdx + 1;

        // Add remove button if not exists
        let header = newRow.querySelector('.d-flex');
        if (!header.querySelector('.remove-guardian-btn')) {
            let rmBtn = document.createElement('button');
            rmBtn.type = 'button';
            rmBtn.className = 'btn btn-sm btn-outline-danger remove-guardian-btn';
            rmBtn.innerText = 'Remove';
            header.appendChild(rmBtn);
        }
        newRow.querySelector('.remove-guardian-btn').setAttribute('data-idx', nextIdx);

        // Update inputs
        let inputs = newRow.querySelectorAll('input, select');
        inputs.forEach(input => {
            let oldName = input.getAttribute('name');
            if (oldName) {
                let newName = oldName.replace(/_\d+$/, '_' + nextIdx);
                input.setAttribute('name', newName);
            }
            input.value = '';
            input.removeAttribute('required');
        });

        container.appendChild(newRow);
        nextIdx++;
    });

    container.addEventListener('click', function(e) {
        if (e.target.classList.contains('remove-guardian-btn')) {
            let row = e.target.closest('.guardian-row');
            if(document.querySelectorAll('.guardian-row').length > 1) {
                row.remove();
            }
        }
    });
});
